		set @sql='ALTER PROCEDURE [dbo].[ccsp_RIACATChatPredefinedMsg]
@message_id varchar(max)=null,
@Description varchar(40)=null,
@message varchar(max)=null,
@Type smallint,
@CamEspId smallint=null,
@serviceId smallint=1
AS
set nocount on
declare @sql nvarchar(1000)

if @Type=1 -- Load
 begin
	Select message_id, description, [message] from ccRIAChatPredefinedMsg where message_status=1 and serviceId = @serviceId order by 2
	return(0)
 end

If @Type=2 -- New
 begin
	If exists(select description from ccRIAChatPredefinedMsg where message_status=1 and description=@Description and serviceId = @serviceId)
	 begin
		select -1
		return(0)
	 end

	declare @msg_id smallint
	set @msg_id = 0
	select top 1 @msg_id=message_id from ccRIAChatPredefinedMsg where message_status=0 and description=@Description
	If @msg_id>0
	begin
		update ccRIAChatPredefinedMsg set message_status=1, [message]=@message where description=@Description
		select @msg_id
		return(0)
	end

	select SCOPE_IDENTITY()
	return(0)
 end

If @Type=3 -- Update
 begin
	If exists(select description from ccRIAChatPredefinedMsg where message_status=1 and message_id=@message_id and serviceId = @serviceId)
	begin
		UPDATE ccRIAChatPredefinedMsg set Description=@Description ,[message]=isnull(@message, [message])
		where message_id in (select value from dbo.fn_RIASplitDelimited(@message_id, '',''))
	end
	
	return(0)
 end

If @Type=4 -- Delete
 begin
	delete from ccRIAChatInboundPredefinedMsg where message_id in (select value from dbo.fn_RIASplitDelimited(@message_id, '','')) and serviceId = @serviceId
	update ccRIAChatPredefinedMsg set message_status=0 where message_id in (select value from dbo.fn_RIASplitDelimited(@message_id, '','')) and serviceId = @serviceId
	return(0)
 end

If @Type=5 --Relation
 begin
	select description from ccRIAChatPredefinedMsg where message_id=@message_id
	return(0)
 end

set nocount off'
		EXEC(@sql)

		set @process = 'ALTER PROCEDURE [dbo].[ccsp_RIAChatPredefinedMsg] -------'
		set @sql='ALTER PROCEDURE [dbo].[ccsp_RIAChatPredefinedMsg]
@Type smallint,
@Type2 smallint,
@IDArea smallint=0,
@CamEspID smallint,
@User_id smallint,
@InsertMessage_id varchar(1000),
@DeleteMessage_id varchar(1000),
@serviceId smallint = 1 --Default Chat
AS
set nocount on

If @Type=1--get ACDGroups
 begin
	if @serviceId = 2 --1 chat, 2 Email
		begin
			set @serviceId = 3
		end
	SELECT a1.Inbound_id, descripcion, a2.graphic_id, a3.frame, a1.chat from ccInbound a1
	inner join ccRIAInboundGraph a2 on(a1.Inbound_id=a2.Inbound_id)
	inner join ccRIAGraphics a3 on(a2.graphic_id=a3.graphic_id)
	where a1.chat = @serviceId and isnull(a1.IDArea, -1) = case when @IDArea=0 then -1
	when (select login from ccusers where user_id = @User_id) = ''root'' then isnull(a1.IDArea, -1)
	else @IDArea end
	order by 2
	return(0)
 end

IF @Type=2--query
 begin
	select i.Inbound_id, descripcion , c.message_id, description, [message]
	from ccInbound i inner join ccRIAChatInboundPredefinedMsg c on i.Inbound_id=c.Inbound_id
	inner join ccRIAChatPredefinedMsg m on m.message_id=c.message_id and m.serviceId=c.serviceId
	where m.message_status=1 and c.serviceId=@serviceId and i.Inbound_id=@CamEspID
	order by 4
	return(0)
 end

If @Type=3--get Areas
 begin
	if exists(select a.* from ccRIACAT_Areas a join ccusers c on a.idarea = c.idarea where a.StatusArea=1 and c.user_id = @user_id)
	and (select login from ccUsers where user_id=@User_id)<>''root''
		select a.* from ccRIACAT_Areas a join ccusers c on a.idarea = c.idarea where a.StatusArea=1 and c.user_id = @user_id
	else
		select * from ccRIACAT_Areas where StatusArea=1 order by AreaName
	return(0)
 end

declare @sql nvarchar(1000), @nIDArea nvarchar(10)

if @Type=4--Insert Message
 begin
	If @Type2=2
	 begin
		If exists(select inbound_id from ccRIAChatInboundPredefinedMsg where inbound_id=@CamEspID and message_id=@InsertMessage_id and serviceId=@serviceId)
			select 2
		else
			if exists(select inbound_id from ccInbound where Inbound_id=@CamEspID)
			and exists(select message_id from ccRIAChatPredefinedMsg where message_status=1 and message_id=@InsertMessage_id and serviceId=@serviceId)
					insert ccRIAChatInboundPredefinedMsg(inbound_id, message_id, serviceId) select @CamEspID, @InsertMessage_id, @serviceId
		return(0)
	 end

	If @Type2=1
	begin
		set @nIDArea = 0
		select @nIDArea=IDArea from ccUsers where USER_ID=@User_id
		if @nIDArea>0
		begin
			set @sql=''insert ccRIAChatInboundPredefinedMsg (inbound_id,message_id,serviceId)
			select distinct a.inbound_id, b.message_id, b.serviceId from ccInbound a, ccRIAChatPredefinedMsg b where
			b.message_id in(''+@InsertMessage_id+'') and b.message_status=1 and b.serviceId=''+cast(@serviceId as nvarchar)+''
			and not exists(select c.inbound_id, e.message_id, e.serviceId from ccRIAChatInboundPredefinedMsg c
			join ccRIAChatPredefinedMsg e on e.message_id=c.message_id and e.serviceId=c.serviceId
			join ccInbound d on d.inbound_id=c.inbound_id and IDArea=''+@nIDArea+
			'' where c.inbound_id=a.inbound_id and b.message_id=e.message_id and b.serviceId=e.serviceId)
			and a.inbound_id in(select x.inbound_id from ccInbound x where IDArea=''+@nIDArea+'' and ((chat>0 and ''+cast(@serviceId as nvarchar)+''=1) || (''+cast(@serviceId as nvarchar)+''<>1)))''
			declare @serviceType int
			if(@serviceId = 1)
				begin
					set @serviceType = 1
				end
			if(@serviceId = 2)
				begin
					set @serviceType = 3
				end
			set @sql=''insert ccRIAChatInboundPredefinedMsg (inbound_id,message_id,serviceId)
			select distinct a.inbound_id, b.message_id, '' + cast(@serviceId as nvarchar) + '' from ccInbound a, ccRIAChatPredefinedMsg b where
			b.message_id in(''+@InsertMessage_id+'') and b.message_status=1 
			and not exists(select c.inbound_id, e.message_id, e.serviceId from ccRIAChatInboundPredefinedMsg c
			join ccRIAChatPredefinedMsg e on e.message_id=c.message_id and e.serviceId=c.serviceId
			join ccInbound d on d.inbound_id=c.inbound_id and IDArea=''+@nIDArea+
			'' where c.inbound_id=a.inbound_id and b.message_id=e.message_id and b.serviceId=e.serviceId)
			and a.inbound_id in(select x.inbound_id from ccInbound x where IDArea=''+@nIDArea+'' and chat = ''+ cast(@serviceType as nvarchar) +'')''
			execute sp_executesql @sql
		end
	end
		return(0)
 end

If @Type=5--Delete Messages
 begin
	If @Type2=2
	 begin
		delete ccRIAChatInboundPredefinedMsg where inbound_id=@CamEspID	and message_id=@DeleteMessage_id and serviceId=@serviceId
		return(0)
	 end

	If @Type2=1
	begin
		set @nIDArea = 0
		select @nIDArea=IDArea from ccUsers where USER_ID=@User_id
		if @nIDArea>0
		begin
			set @sql=''delete ccRIAChatInboundPredefinedMsg where inbound_id in(select inbound_id from
			ccInbound where IDArea=''+@nIDArea+'') and message_id in(''+@DeleteMessage_id+'') and serviceId ='' + cast(@serviceId as nvarchar)
			execute sp_executesql @sql
		end
		return(0)
	end
 end

 If @Type=6 --get Areas
 begin
	select a.* from ccRIACAT_Areas a join ccusers c on a.idarea = c.idarea where a.StatusArea=1 and c.user_id = @user_id
	return(0)
 end

return(0)
set nocount off'
		EXEC(@sql)




		set @process = 'Alter Procedure [dbo].[ccsp_RIARegistryLists] -------'
		set @sql='Alter Procedure [dbo].[ccsp_RIARegistryLists]
@action tinyint = 0, 
@list_id int = 0,
@cam_id smallint = 0,
@name varchar(80) = '''',
@status tinyint = 0,
@sequence smallint = 0
AS

--Status lista 0: inactiva, 1:pausa, 2:procesar

--Insert
IF @action = 1 begin

	IF @cam_id <> 0 begin
		select @sequence = isnull(max( sequence ),0) from ccRIARegistryLists where cam_id = @cam_id
		set @sequence = @sequence + 1
		select max(list_id) from ccRIARegistryLists
	end
end

--Update sequence
IF @action = 2 begin
	
	declare @oldSeq as int
	select @oldSeq = sequence, @cam_id = cam_id from ccRIARegistryLists where list_id = @list_id

	if @oldSeq <> @sequence begin
		
		if @oldSeq > @sequence begin
			update ccRIARegistryLists set sequence = sequence + 1 where cam_id = @cam_id and sequence >= @sequence and sequence < @oldSeq
		end

		if @oldSeq < @sequence begin
			update ccRIARegistryLists set sequence = sequence - 1 where cam_id = @cam_id and sequence <= @sequence and sequence > @oldSeq
		end

		update ccRIARegistryLists set sequence = @sequence where list_id = @list_id

	end

end

--Change status
IF @action = 3 begin
	
	update ccRIARegistryLists set status = @status where list_id = @list_id

end

-- lista campañas y listas de registros
IF @action = 4 begin
	select a.cam_id, b.cam_descripcion, count(list_id) as NoListas, c.graphic_id as Frame from ccRIARegistryLists a 
	left join cccamps b on a.cam_id = b.cam_id
	left join ccRIACampsGraph c on a.cam_id = c.cam_id
	where b.cam_activo = 1 and a.cam_id in ( select distinct(cam_id) from ccRIARegistryLists ) 
	group by a.cam_id,b.cam_descripcion,c.graphic_id order by a.cam_id asc

end

-- listas de registros y no. registros
IF @action = 5 
begin
	select a.list_id,a.name,count(b.list_id) as NoRegistros,a.sequence   
	from ccRIARegistryLists a with(index(IX_ccRIARegistryLists_1),nolock) 
	left join ccocallsoutsource b with(index(IX_ccoCallsOutSource_13),nolock) 
	on b.cam_id = @cam_id and a.list_id = b.list_id 
	where a.status > 0 and a.cam_id = @cam_id and status > 0 
	group by a.list_id,a.name,a.sequence 
	order by a.sequence
end

-- borrar lista
IF @action = 6 begin

	select @cam_id = cam_id from ccRIARegistryLists where list_id = @list_id
	select @sequence = max(sequence) from ccRIARegistryLists where cam_id = @cam_id
	exec ccsp_RIARegistryLists @action = 3, @status = 0, @list_id = @list_id
	exec ccsp_RIARegistryLists @action = 2, @sequence = @sequence, @list_id = @list_id

end

-- Detalle de numero de registros
IF @action = 7 begin

	declare @total as int

	select @total = count(*) from ccocallsoutsource where list_id = @list_id
	select @total = (@total - count(*)) from ccoworkingtable where list_id = @list_id

	if exists(select list_id from ccoWorkingTable where list_id = @list_id) begin
		select @status = status from ccRIARegistryLists where list_id = @list_id
		select @list_id as list_id,cam_id, @status as status,
			count(case cal_status when 0 then 1 else null end) as New,
			count(case cal_status when 1 then 1 else null end) as CB,
			count(case cal_status when 2 then 1 else null end) as Pro, 
			@total as Fin
		from ccoWorkingTable where list_id = @list_id group by cam_id
	end
	ELSE begin
		select list_id, cam_id, status, 
		0 as New,
		0 as CB,
		0 as Pro,
		0 as Fin
		from ccRIARegistryLists where list_id = @list_id
	end


end

-- Cambia de nombre a la lista
IF @action = 8 begin
	
	update ccRIARegistryLists set name = @name where list_id = @list_id

end

-- Borra listas sin registros y reordena las listas
IF @action = 9 begin

	Create table TempRegs(
		list_id int,
		[name] varchar(100),
		NoRegistros int,
		sequence int)

		select a.list_id,a.name,count(b.list_id) as NoRegistros,a.sequence 
		from ccRIARegistryLists a with(index(IX_ccRIARegistryLists_1),nolock)
		left join ccocallsoutsource b with(index(IX_ccoCallsOutSource_14),nolock)
		on a.list_id = b.list_id
		where a.status > 0 and a.cam_id = @cam_id and status > 0 
		group by a.list_id,a.name,a.sequence,a.status order by a.sequence

	while ( exists( select list_id from TempRegs where NoRegistros = 0 ) ) begin
		declare @listToDelete as int
		select top 1 @listToDelete = list_id from TempRegs where NoRegistros = 0
		exec ccsp_RIARegistryLists @action = 6, @list_id = @listToDelete
		delete from TempRegs where list_id =  @listToDelete
	end

	drop table TempRegs
	
	select @sequence=min(sequence) from ccRIARegistryLists where  cam_id = @cam_id and status = 0 

	select @list_id= list_id from ccRIARegistryLists where sequence =(
	select  max(sequence) as sequence from ccRIARegistryLists where  cam_id = @cam_id and status > 0 ) and cam_id = @cam_id

	exec ccsp_RIARegistryLists @action=2,@list_id=@list_id,@sequence=@sequence

end'
		EXEC(@sql)


		set @process = 'ALTER PROCEDURE [dbo].[ccsp_RIAManageAreas] -------'
		set @sql='ALTER PROCEDURE [dbo].[ccsp_RIAManageAreas]
				@option tinyint,
				@IDArea smallint = 0,
				@InsertUserId smallint =null,
				@DeleteUserId varchar(255)=null,
				@InsertCamId smallint=null,
				@DeleteCamId smallint=null,
				@InsertACDGroupId smallint=null,
				@DeleteACDGroupId smallint=null
				as
				set nocount on

				if @option = 1 -- Insert User Area
				 begin
					if not exists(select IDArea from ccUsers where IDArea = @IDArea AND User_id = @InsertUserId)
					 begin
						Update ccUsers set IDArea = @IDArea, status = 1 where User_id = @InsertUserId
						return(0)
					 end	
					 
					select 1
					return(0)
				 end

				if @option = 3 -- Insert camp area
				 begin
					if not exists(select IDArea from ccCamps where IDArea = @IDArea and cam_id = @InsertCamId)
					 begin
						Update ccCamps set IDArea = case @IDArea when 0 then null else @IDArea end
						where cam_id = @InsertCamId
						return(0)
					 end

					select 1
					return(0)
				 end

				if @option = 4 -- Delete camp area
				 begin
				 
					delete from ccCampsAgente where cam_id = @DeleteCamId
					--delete from ccoDialerCamp where cam_id = @DeleteCamId
					delete from ccoWorkingTable where cam_id = @DeleteCamId


					delete from ccSupervisorCam where cam_id = @DeleteCamId and tipo = 1
					delete from ccRIACampEspWG where IdCampEsp = @DeleteCamId and tipo = 1	
					delete from ccoWorkingTable where callout_id in (select callout_id from ccoCallsOutSource where cam_id = @DeleteCamId)

					if exists(select cam_id from ccInbound where cam_id=@DeleteCamId)
					 begin
						select -4
						return(0)	 
					 end

					Update ccCamps set IDArea= null where cam_id=@DeleteCamId--, cam_activo = 0 
					return(0)
				 end

				if @option = 5 -- Insert ACDGroup area
				 begin
					if not exists(select IDArea from ccInbound where IDArea = @IDArea and Inbound_Id = @InsertACDGroupId)
					 begin
						Update ccInbound set IDArea = @IDArea, status = 1 where Inbound_id = @InsertACDGroupId
						return(0)
					 end

					select 1
					return(0)
				 end

				if @option = 6 -- Delete ACDGroup area
				 begin

					delete ccInboundHorarios Where Inbound_id = @DeleteACDGroupId
					delete ccInboundMsgs Where Inbound_id = @DeleteACDGroupId


					delete ccSupervisorCam where cam_id = @DeleteACDGroupId and tipo = 0
					delete ccInboundAgentes where Inbound_id = @DeleteACDGroupId
					delete ccRIACampEspWG where IdCampEsp = @DeleteACDGroupId and tipo = 0

					Update ccInbound set IDArea = null, status = 0 where Inbound_id = @DeleteACDGroupId
					select 1
					return(0)
				 end

				if @option in (2, 9, 10, 11)
				 begin
						declare @Type tinyint
					select @Type = TipoUser_id from ccUsers where User_id = @DeleteUserId
					
					if @option in (2, 10, 11) -- Delete User area
					 begin
						if @Type = 1 -- Agente
						 begin


							delete from ccCampsAgente where user_id = @DeleteUserId
							delete from ccInboundAgentes where user_id = @DeleteUserId

							if @option = 11
								begin
									select IDWG, User_id into #WorkGroupUsers from ccRIAWorkGroupUsers where user_id = @DeleteUserId

									delete from ccRIAWorkGroupUsers where user_id = @DeleteUserId
									
									select * from #WorkGroupUsers
									drop table #WorkGroupUsers
									
									return(0)
								end
						 end

						else if @Type in (2, 6) -- Supervisor
						begin
							delete from ccSupervisorCam where user_id = @DeleteUserId
						end

						delete from ccRIAWorkGroupUsers where user_id = @DeleteUserId
						
						if @option=2
						 begin
							update ccPosicion set user_id = 0 where user_id = @DeleteUserId
							update ccUsers set IDArea = null where user_id = @DeleteUserId	
						 end
						return(0)
					end

					declare @UserWG varchar(100)
					-- @option = 9 -- Delete User area and get his workgroups

					select @UserWG = IDWG from ccRIAWorkGroupUsers where user_id = @DeleteUserId

					if @Type = 1 -- Agente
					 begin

						delete from ccCampsAgente where user_id = @DeleteUserId
						delete from ccInboundAgentes where user_id = @DeleteUserId
					 end

					if @Type in (2, 6) -- Supervisor
					 begin

				 		delete from ccSupervisorCam where user_id = @DeleteUserId
						delete from ccMenuUser where id_User = @DeleteUserId
					 end

					delete from ccRIAWorkGroupUsers where user_id = @DeleteUserId
					update ccPosicion set user_id = 0 where user_id = @DeleteUserId
					
					if @option <> 11
						update ccUsers set IDArea = null where user_id = @DeleteUserId
					
					select @UserWG, @Type
					return(0)
				 end

				declare @AllWG varchar(400), @CurrentWG varchar(400), @AreaDescripcion varchar(40)

				if @option = 7 -- Delete camp area
				 begin
						if exists(select cam_id from ccInbound where cam_id=@DeleteCamId)
					begin
						update ccInbound set cam_id = null where cam_id=@DeleteCamId		 
					end

					select @AllWG = coalesce(@AllWG + '''','''', '''') + CAST(IDWG as varchar(400)) 
					from ccRIACampEspWG where IDCampEsp = @DeleteCamId and tipo = 1


					delete from ccCampsAgente where cam_id = @DeleteCamId
					delete from ccoWorkingTable where cam_id = @DeleteCamId or callout_id 
					 in (select callout_id from ccoCallsOutSource where cam_id = @DeleteCamId)


					delete from ccSupervisorCam where cam_id = @DeleteCamId and tipo = 1
					delete from ccRIACampEspWG where IdCampEsp = @DeleteCamId and tipo = 1	

					select @CurrentWG = coalesce(@CurrentWG + '''','''', '''') + CAST(IDWG as varchar(400)) 
					from ccRIACampEspWG where IDCampEsp = @DeleteCamId and tipo = 1

					select @AreaDescripcion = area.AreaName
					from ccCamps as camp with(nolock)inner join ccRIACat_Areas as area 
					 with(nolock) on camp.IDArea = area.IDArea
					where camp.cam_id = @DeleteCamId
					Update ccCamps set IDArea = null where cam_id = @DeleteCamId

					If @CurrentWG is null
						set @CurrentWG = 0

					If @AllWG is null
						set @AllWG = 0

					select @AllWG as beforeDelete, @CurrentWG as afterDelete, coalesce(@AreaDescripcion,'''') as areaName
					return(0)
				 end

				if @option = 8 --Delete ACDGroup area
				 begin
					if (select cam_id from ccInbound where Inbound_id = @DeleteACDGroupId) is not null
					begin
						update ccInbound set cam_id = null where Inbound_id = @DeleteACDGroupId
					end

					select @AllWG = coalesce(@AllWG + '''','''', '''') + CAST(IDWG as varchar(400)) 
					from ccRIACampEspWG where IDCampEsp = @DeleteACDGroupId and tipo = 0


					delete ccInboundHorarios Where Inbound_id = @DeleteACDGroupId
					delete ccInboundMsgs Where Inbound_id = @DeleteACDGroupId


					delete ccSupervisorCam where cam_id = @DeleteACDGroupId and tipo = 0
					delete ccInboundAgentes where Inbound_id = @DeleteACDGroupId
					delete ccRIACampEspWG where IdCampEsp = @DeleteACDGroupId and tipo = 0

					select @CurrentWG = coalesce(@CurrentWG + '''','''', '''') + CAST(IDWG as varchar(400)) 
					from ccRIACampEspWG where IDCampEsp = @DeleteACDGroupId and tipo = 0

					select @AreaDescripcion = area.AreaName
					from ccInbound as ACD with(nolock) inner join ccRIACat_Areas as area 
					 with(nolock) on ACD.IDArea = area.IDArea
					where ACD.Inbound_id = @DeleteACDGroupId
					Update ccInbound set IDArea = null, status = 0 where Inbound_id = @DeleteACDGroupId

					If @CurrentWG is null
						set @CurrentWG = 0

					If @AllWG is null
						set @AllWG = 0

					select @AllWG as beforeDelete, @CurrentWG as afterDelete, coalesce(@AreaDescripcion,'''') as areaName
					return(0)
				 end

				return(0)
				set nocount off'
		EXEC(@sql)


		set @process = 'ALTER PROCEDURE [dbo].[ccsp_GetAgentIndividualCounters] -------'
		set @sql='ALTER PROCEDURE [dbo].[ccsp_GetAgentIndividualCounters] @type as int, @sup_id as int = 0 as
set nocount on

declare @fecha_ini datetime
select @fecha_ini = convert(datetime,convert(varchar(11),getdate()))

if @type = 1 --Session time
	begin
		SELECT User_id, case
			WHEN sum(convert(int,DateDiff(second, ''00:00'', Convert(VARCHAR(30), fecha, 14)))*(1-2*tipomov)) > 0
				THEN sum(convert(int,DateDiff(second, ''00:00'', Convert(VARCHAR(30), fecha, 14)))*(1-2*tipomov))
			ELSE sum(convert(int,DateDiff(second, ''00:00'', Convert(VARCHAR(30), fecha, 14)))*(1-2*tipomov)) +
				convert(int,DateDiff(second, ''00:00'', Convert(VARCHAR(30), getdate(), 14)))
			END as logintime
		FROM ccLogLogin a with(index(IX_ccLogLogin_4)), ccGenViewRelsSupsAgent b
		where fecha >= @fecha_ini
		and a.User_id = b.agt
		and b.sup = @sup_id
		GROUP BY User_id
	end

if @type = 2 --Status agent
	begin
		SELECT User_id, TipoStatusAge_id, sum(tStatus) As segundos
		FROM ccLogAgentesDia a with(index(IX_ccLogAgentesDia_4)), ccGenViewRelsSupsAgent b
		WHERE fecha >= @fecha_ini
		AND a.User_id = b.agt
		and b.sup = @sup_id
		GROUP BY User_id, TipoStatusAge_id
		ORDER BY User_id
	end

if @type = 3
	begin

		select calls.user_id, calls.total_calls, calls.type_calls, users.login, calls.nCalls, calls.tDialog, calls.tWrapup, calls.tHold
		from ccusers As users ,
		(
			SELECT User_id AS ''user_id'' , count(*) AS ''total_calls'',
			CASE
			  WHEN statuscall_id = 15 THEN 5  --OutBound Asignada pero no contestada
			  WHEN cal_manual = 2 THEN 3      --OutBound llamada manual
			  ELSE 2                          --Llamada de OutBound
			END AS ''type_calls'',
			count(case when statuscall_id=13 and cal_tdialog>0 then 1 else null end) nCalls,
			sum(case when statuscall_id=13 and cal_tdialog>0 then cal_tdialog else 0 end) tDialog,
			sum(case when statuscall_id=13 and cal_tdialog>0 then cal_tnotas else 0 end) tWrapup,
			sum(case when statuscall_id=13 and cal_tdialog>0 then cal_tMoh else 0 end) tHold
			FROM ccoCallsOut a WITH (NOLOCK index(IX_ccoCallsOut_10)) , ccGenViewRelsSupsAgent b
			WHERE a.User_id = b.agt
			and b.sup = @sup_id
			AND statuscall_id <> 11  --OutBound sin estado definitivo
			AND cal_inicio >= @fecha_ini
			GROUP BY User_id, statuscall_id, cal_manual

			UNION

			SELECT User_id AS ''user_id'' , count(*) AS ''total_calls'',
			CASE
			  WHEN statuscall_id = 15 THEN 4  --InBound Asignada pero no contestada
			  ELSE 1                          --Llamada de InBound
			END AS ''type_calls'',
			count(case when statuscall_id=13 and cal_tdialog>0 then 1 else null end) nCalls,
			sum(case when statuscall_id=13 and cal_tdialog>0 then cal_tdialog else 0 end) tDialog,
			sum(case when statuscall_id=13 and cal_tdialog>0 then cal_tnotas else 0 end) tWrapup,
			sum(case when statuscall_id=13 and cal_tdialog>0 then cal_tMoh else 0 end) tHold
			FROM ccCallsIn a WITH (NOLOCK index(IX_ccCallsIn_5)), ccGenViewRelsSupsAgent b
			WHERE a.User_id = b.agt
			and b.sup = @sup_id
			AND statuscall_id <> 11  --InBound sin estado definitivo
			AND cal_inicio >= @fecha_ini
			GROUP BY User_id, statuscall_id
		) AS calls
		where users.user_id = calls.user_id

	end

if @type = 4
	begin
		select a.user_id, a.login
		from ccusers a, ccGenViewRelsSupsAgent b
		where user_id = b.agt
		and b.sup = @sup_id
	end

