drop table #mycamps'
		EXEC(@sql)

		set @process = 'ALTER PROCEDURE [dbo].[ccsp_RIA_ABCCamps] ------------------'
		set @sql='ALTER PROCEDURE [dbo].[ccsp_RIA_ABCCamps]
@option smallint,
@UserId int,
@Descripcion varchar(40),
@Cam_id varchar(1000),
@Activa tinyint,
@IDArea smallint = null,
@frame tinyint, 
@MirrorInbound_Id smallint = null
as
set nocount on

if @option = 0
 begin
	 select cam_id,ISNULL(cam_descripcion,'''') as cam_descripcion,ISNULL(CAMP.IDArea,0) as IDArea, ISNULL(AREas.AreaName,'''') as AreaName
	 from ccCamps as CAMP with(nolock) 
	 left join ccRIACat_Areas as AREas with(nolock) on CAMP.IDArea = AREas.IDArea
	 return(0)
 end

if @option = 1 -- select Camp
 begin
	 select a1.cam_id, cam_descripcion, cam_ShowCalifWnd,cam_StartTimeronHangUp, frame, cam_activo, isnull(IDArea,0)
	 from ccCamps a1 with(nolock) 
	  inner join ccRIACampsGraph a2 on (a1.cam_id = a2.cam_id)
	  inner join ccRIAGraphics a3 on (a2.graphic_id = a3.graphic_id)
	 where a3.type_id = 1 and a1.cam_id = (CasT(@Cam_id as smallint))
	 return(0)
 end

if @option = 4 --Delete
 begin
 	 if exists (select inbound_id from ccInbound with(nolock) where cam_id = @Cam_id)
	  begin
		declare @error varchar(70)
		Select @error=case valor when 0 then ''No es posible eliminar la campaña, esta asociada a una especialidad'' 
		 else ''Campaign can not be deleted, it has an association with an ACD'' end
		from ccsettings with(nolock) where setting_id = 27
		raiserror (@error,18,1)		
		return(0)
	  end

	 delete ccCampsHorarios with(rowlock) where cam_id = @Cam_id
	 Delete ccCalifCamp with(rowlock) where cam_id = @Cam_id and tipo = 1
	 Delete ccRIACampsGraph with(rowlock) where cam_id = @Cam_id
	 delete ccHistorialListaNegra with(rowlock) where cam_id = @Cam_id
	 delete ccRIARegistryLists with(rowlock) where cam_id = @Cam_id	
	 return(0)
 end

if @option = 2 --Insert
 begin
	declare @new_cam_id smallint

	if exists(select cam_descripcion from ccCamps with(nolock) where cam_descripcion = @Descripcion)
	 begin
		select -1 --, ''Nombre en Uso''
		return(0)  
	 end

	-- ODC: la campaña siempre esta activa
	set @Activa = 1

	select @Descripcion, 1, @Activa, case @IDArea when 0 then null else @IDArea end, 1,
	case when exists (select calif_id from ccTipoCalifOUT) then 1 else 0 end

	if @@rowcount = 1
	select @new_cam_id = scope_identity()

	else
	 begin
		select -2 --, ''Error al crear campaña''
		return(0)
	 end

	if isnull(@MirrorInbound_Id, 0)<>0
	 begin
		if not exists(select inbound_id from ccInbound with(nolock) where inbound_id=@MirrorInbound_Id)
		 begin
			select -3 -- Error al asignar campaña a ACD, el ACD no existe o no pertenece a la misma area
			return(0)
		 end

		update ccinbound with(rowlock) set cam_id=@new_cam_id where inbound_id=@MirrorInbound_Id -- and isnull(idarea, 0)=isnull(@IDArea, 0)
		update cccamps with(rowlock) set idarea = (select idarea from ccinbound where inbound_id=@MirrorInbound_Id) where cam_id=@new_cam_id
	 end

	select dialer_id, @new_cam_id from ccoDialers with(nolock) where status = 1

	select calif_id, @new_cam_id, 1 from ccTipoCalifOUT with(nolock) where CalifOut_Status = 1

	If not exists (select frame from ccRIAGraphics with(index(IX_ccRIAGraphics_I),nolock) where frame = @frame and type_id = 1)
	 begin
	 end

	select @new_cam_id, graphic_id from ccRIAGraphics with(index(IX_ccRIAGraphics_I),nolock)  where frame = @frame and type_id = 1

	--inserta la lista negra por default
	if (select valor from ccsettings with(nolock) where setting_id=152)=''1''
	begin
		declare @tempId as int
		DECLARE @dnclId TABLE 
		(
		  id int 
		);
		exec dbo.ccsp_RIACATBList null, null, 5
		select @tempId=id from @dnclId;
		exec ccsp_RIABlackListCamp 4, @IDArea, @new_cam_id, @tempId, null
	end

	select @new_cam_id
	return(0)
 end

if @option = 3 -- Update
 begin
	 if not exists(select frame from ccRIAGraphics with(index(IX_ccRIAGraphics_I),nolock) where frame = @frame and type_id = 1)

	 Update ccCamps with(rowlock) set cam_descripcion = @Descripcion, cam_activo = @Activa where cam_id = @Cam_id

	 update ccRIACampsGraph with(rowlock)
	  set graphic_id = (select graphic_id from ccRIAGraphics with(index(IX_ccRIAGraphics_I),nolock) where frame = @frame and type_id = 1)
	  where cam_id = @Cam_id

	 return(0)
 end

 if @option = 5 --Obtener relaciones de campañas - campañas
   begin
      if not exists (select cam_id from ccCamps with(nolock) where cam_id = @Cam_id) or
	 (@descripcion is not null and @descripcion <> '''' and @descripcion <> ''0'' and 
		not exists (select cam_id from ccCamps with(nolock) where cam_id=@descripcion))
	 begin
		select -3 -- Campaña invalida
		return(0)
	 end
	
	if @descripcion=0
		set @descripcion = null

	update ccCamps with(rowlock) set surveyCamId = @descripcion where cam_id = @Cam_id
	if @@rowcount=0
		select -4 -- Error al actualizar
		
	else
	 begin
		delete cccalifcamp with(rowlock) where tipo=0 and cam_id=@Cam_id and calif_id in (select calif_id from ccTipoCalif where CanReprogram=1)

	 end

	return(0)
   end

if @option = 6
	begin
		select cam_id, isnull(surveycamid,0)
		from cccamps with(index(PK_ccCamps),nolock)
		where cam_id = @Cam_id
		return(0)
	end

return(0)
set nocount off'
		EXEC(@sql)

		set @process = 'ALTER proc [dbo].[ccsp_RIA_mnuReciclar]-----'
		set @sql='ALTER proc [dbo].[ccsp_RIA_mnuReciclar]
@cam_id int,
@type tinyint, -- 0:recicla todo / 1:recicla no efectivos / 2:recicla los efectivos calificados / 
--				  3:recicla no efectivos y efectivos calificados (1 y 2) / 4:Recicla status "Finalizado"
@calif_id varchar(1500) = null,
@user_id as integer = null,
@list_id as integer = 0
as
set nocount on
declare @Valor int, @SQL varchar(4000)
select @Valor = valor from ccSettings with(nolock) where setting_id = 60

If @Valor = 1
 begin
	declare @ultimoReciclaje datetime, @siguienteReciclaje datetime, @difDateAdd datetime
	select @Valor = valor from ccSettings with(nolock) where setting_id = 59
	
	If @Valor = 0 
	 begin
		select -2, ''No hay un limite para volver a reciclar''
		return(0)
	 end

	select top 1 @ultimoReciclaje = max(fecha) from ccLogReciclaje where cam_id = @cam_id

	-- Se crea log, ccsp_ADMlogReciclaje para que esta informacion la traiga, por que no se esta metiendo
	select @user_id = isnull(@user_id, ''0''), @calif_id = isnull(@calif_id, ''0'')
	
	exec dbo.ccsp_ADMlogReciclaje @cam_id, @user_id, @type, @calif_id

	If @ultimoReciclaje is not null and getdate() < DateAdd(n, @Valor, @ultimoReciclaje)
	begin
		select -3, ''No se puede realizar un reciclaje hasta que pase el tiempo limite''
 		return(0)
	end

 end

if @type=0
 begin
	if @list_id = 0 begin
		create table #allReciycled(callout_id int not null primary key)

		select callout_id from ccoWorkingTable with(index(IX_ccoWorkingTable_9),nolock) where cam_id = @cam_id and cal_status = 1

		update ccoCallsOutSource with(rowlock) 
		set dato5 = isnull(dato5, '''') 
		from ccoCallsOutSource a join #allReciycled b on (a.callout_id = b.callout_id)

		update ccoCallBacks with(rowlock)
		set [status] = 3, schedulerStatus = 1
		from ccoCallBacks a with(index([IX_ccoCallBacks6])) join #allReciycled b on (a.callout_id = b.callout_id)
		where [status] = 0

		update ccoWorkingTable with(rowlock) 
		set cal_status = 0 
		from ccoWorkingTable a join #allReciycled b on (a.callout_id = b.callout_id)

		drop table #allReciycled
	end
	else begin
		create table #allListReciycled(callout_id int not null primary key)

		select callout_id from ccoWorkingTable with(index(IX_ccoWorkingTable_10),nolock) where cam_id = @cam_id and cal_status = 1 and list_id = @list_id

		update ccoCallsOutSource with(rowlock) 
		set dato5 = isnull(dato5, '''') 
		from ccoCallsOutSource a join #allListReciycled b on (a.callout_id = b.callout_id)

		update ccoCallBacks with(rowlock)
		set [status] = 3, schedulerStatus = 1
		from ccoCallBacks a with(index([IX_ccoCallBacks6])) join #allListReciycled b on (a.callout_id = b.callout_id)
		where [status] = 0

		update ccoWorkingTable with(rowlock) 
		set cal_status = 0 
		from ccoWorkingTable a join #allListReciycled b on (a.callout_id = b.callout_id)

		drop table #allListReciycled
	end

	return(0)
 end

if @type in(1,3)
 begin
	update ccoCallsOutSource with(rowlock)
	set dato5 = isnull(dato5, '''') where callout_id in (
	 select callout_id from ccoWorkingTable with(index(IX_ccoWorkingTable_11),nolock)
	 where cam_id = @cam_id and cal_status = 1 and tiporesdial_id <> 1)

	update ccoCallBacks with(rowlock)
	set [status] = 3, schedulerStatus = 1
	where callout_id in (select distinct(callout_id)
						 from ccoWorkingTable with(index(IX_ccoWorkingTable_12),nolock)
						 where cam_id = @cam_id 
						 and cal_status = 1 
						 and tiporesdial_id <> 1
						 and callout_id in (select distinct(b.callout_id)
												from ccologdials a with (index (IX_ccoLogDials_4),nolock) 
												left join ccocallsout b with(index(IX_ccoCallsOut12),nolock)
												on a.callout_id = b.callout_id
												and convert(varchar(13), a.fecha, 121) = convert(varchar(13), b.cal_inicio, 121)
												where calif_id = 0
												and calif_id is not null))
	and [status] = 0

	update ccoWorkingTable with(rowlock)
	set cal_status = 0, tiporesdial_id = 0 
	where cam_id = @cam_id 
	and cal_status = 1 
	and tiporesdial_id <> 1
	and callout_id in (select distinct(b.callout_id)
						   from ccologdials a with (index (IX_ccoLogDials_4),nolock) 
						   left join ccocallsout b with(index(IX_ccoCallsOut12),nolock)
						   on a.callout_id = b.callout_id
						   and convert(varchar(13), a.fecha, 121) = convert(varchar(13), b.cal_inicio, 121)
						   where calif_id = 0
						   and calif_id is not null)
 end

if @type in(2,3)
 begin
	Set @SQL = ''update ccoCallsOutSource with(rowlock) set dato5 = isnull(dato5, '''''''') where callout_id in ('' +
	 ''select distinct(callout_id) from ccoWorkingTable with(index(IX_ccoWorkingTable_13),nolock) '' +
	 ''where cam_id = '' + cast(@cam_id as varchar(10)) + '' and cal_status = 1 and tiporesdial_id = 1 '' +
	 ''and calif_id in ('' + @calif_id + '')''+'')'' + nchar(13)
	exec(@SQL)

	Set @SQL = ''update ccoCallBacks with(rowlock) set [status] = 3, schedulerStatus = 1'' +
	 ''where callout_id in ('' +
	 ''select distinct(callout_id) from ccoWorkingTable with(index(IX_ccoWorkingTable_14),nolock) '' +
	 ''where cam_id = '' + cast(@cam_id as varchar(10)) + '' and cal_status = 1 '' +
	 ''and calif_id in ('' + @calif_id + ''))'' +
	 ''and [status] = 0''

	exec(@SQL)

	Set @SQL = ''update ccoWorkingTable with(rowlock) set cal_status = 0, tiporesdial_id = 0, calif_id = 0 '' +
	 ''where cam_id = '' + cast(@cam_id as varchar(10)) + '' and cal_status = 1 ''
	 + -- and tiporesdial_id = 1 '' +
	 ''and calif_id in ('' + @calif_id + '')''

	exec(@SQL)
 end

if @type = 4
 begin
	update ccoCallsOutSource with(rowlock) 
	set dato5 = isnull(dato5, '''') 
	where callout_id in (select distinct(callout_id)
					     from ccoWorkingTable with(index(IX_ccoWorkingTable_9),nolock) 
						 where cam_id = @cam_id and cal_status = 3)

	update ccoCallBacks with(rowlock) 
	set [status] = 3, schedulerStatus = 1
	where callout_id in (select distinct(callout_id)
						 from ccoWorkingTable with(index(IX_ccoWorkingTable_9),nolock) 
						 where cam_id = @cam_id and cal_status = 3)
	and [status] = 0

	update ccoWorkingTable with(rowlock) set cal_status = 0, tiporesdial_id = 0 
	where cam_id = @cam_id and cal_status = 3
 end

return(0)
set nocount off'
		EXEC(@sql)
		
		set @process = 'ALTER PROCEDURE [dbo].[ccsp_RIADialerAssignment]--------'
		set @sql='ALTER PROCEDURE [dbo].[ccsp_RIADialerAssignment]
@User_Id smallint,
@cam_id smallint,
@dialer_id varchar(4000),
@Type2 tinyint,
@Type tinyint
AS
set nocount on
declare @SQL as nvarchar(4000), @nUser_id as nvarchar(10), @params as nvarchar(1000)

If @Type=0--get ports
 begin
	select a.dialer_id, a.puerto, a.Descripcion, b.descrip from ccoDialers a with(index([IX_ccoDialers_I]),nolock)
	inner join cstoProvedor b with(index(PK_cstoProvedor),nolock) on a.provedor_id=b.provedor_id
	order by a.dialer_id
	return(0)
 end

If @Type=1--get cams
 begin
	SELECT a1.cam_id, cam_descripcion FROM ccCamps a1 with(nolock)
	inner join ccRIACampsGraph a2 with(nolock) on(a1.cam_id=a2.cam_id)
	inner join ccRIAGraphics a3 with(nolock) on(a2.graphic_id=a3.graphic_id)
	where a1.cam_id in (select cam_id from dbo.fGet_CampAcd_Area (@User_id, 1))
	order by cam_descripcion
	return(0)
 end

If @Type=2--get port/cam relation
 begin
	select c.cam_id, cd.dialer_id, d.descripcion,
	d.puerto, e.descrip from ccCamps c with(nolock)
	left join ccoDialerCamp cd on cd.cam_id=c.cam_id
	left join ccoDialers d with(index(IX_ccoDialers_I),nolock) on cd.dialer_id=d.dialer_id
	inner join cstoProvedor e with(index(PK_cstoProvedor),nolock) on d.provedor_id=e.provedor_id
	where c.cam_id=@cam_id
	ORDER BY c.cam_id, cd.dialer_id
	return(0)
 end

If @Type=3--delete port/dialer relation
 begin
	If @Type2=1--Sistema
	 begin
		set @nUser_id=@User_Id
		set @sql=''delete ccoDialerCamp with(rowlock) where dialer_id in('' + @dialer_id + '')''
		execute sp_executesql @sql
		return(0)
	 end

	If @Type2=2--Camp
	 begin
		delete ccoDialerCamp with(rowlock) where cam_id=@cam_id and dialer_id=@dialer_id
		return(0)
	 end
 end

If @Type=4--insert new relation
 begin
	If @Type2=1--Sistema
	 begin
		set @nUser_id=@User_Id
		set @sql=''insert ccoDialerCamp(cam_id, dialer_id)
		select a.cam_id, b.dialer_id from ccCamps a, ccoDialers b where
		b.dialer_id in('' + @dialer_id + '') and not exists(
		select c.cam_id, c.dialer_id from ccoDialerCamp c
		where b.dialer_id=c.dialer_id and a.cam_id=c.cam_id)''
		execute sp_executesql @sql
		return(0)
	 end

	If @Type2=2--Camp
	 begin
		set @params=''@Ncam_id int''
 		set @sql=''insert ccoDialerCamp(cam_id, dialer_id) select distinct @Ncam_id,
 		dialer_id from ccCamps, ccoDialers where dialer_id not in(select dialer_id
 		from ccoDialerCamp where dialer_id in('' + @dialer_id + '')and cam_id=@Ncam_id)
		and dialer_id in('' + @dialer_id + '')''
		execute sp_executesql @sql, @params, @Ncam_id=@cam_id
		return(0)
 	 end
 end

If @Type=5--Get existance of dialers
 begin
	if exists (select c.cam_id, cd.dialer_id, d.descripcion,
			   d.puerto, e.descrip from ccCamps c with(nolock)
			   left join ccoDialerCamp cd with(nolock) on cd.cam_id=c.cam_id
			   left join ccoDialers d with(nolock) on cd.dialer_id=d.dialer_id
			   inner join cstoProvedor e with(nolock) on d.provedor_id=e.provedor_id
			   where c.cam_id = @cam_id)
		select 0
	else
		select 13
	return(0)
 end'
		EXEC(@sql)

		set @process = 'ALTER PROCEDURE [dbo].[ccsp_RIAGetCampsNvosCB]---------'
		set @sql='ALTER PROCEDURE [dbo].[ccsp_RIAGetCampsNvosCB] @cam_id integer = 0, @Tipo tinyint = 0, @user_id int = 0 as
set nocount on

declare @regval as int



-- Actualiza todas las camps
if @Tipo=2
	begin
		declare @ultimo as datetime,@id AS INTEGER

		select @ultimo = isnull( convert(datetime, valor, 121), dateadd(hh, -1, getdate() ) ) from ccSettings with(nolock) where setting_id = 21

		if datediff(ss, @ultimo, getdate()) > 120
			begin
				CREATE TABLE #Tcamps
				(cam_id int,
				cantidad int)

				DECLARE CCamp CURSOR FOR 
				select cam_id from ccCamps

				Open CCamp
				Fetch Next From CCamp
				Into @id
				if @@FETCH_STATUS = 0
					Begin 
						While @@FETCH_STATUS = 0
							Begin 
								EXEC @regval = ccsp_OUTGetNewJobs @id,2,0

								INSERT #Tcamps
								select @id,@regval
								Fetch Next From CCamp
								Into  @id
							End
					End
				CLOSE CCamp
				DEALLOCATE CCamp

				UPDATE ccSettings set valor = convert( varchar(23), getdate(),121) where setting_id = 21

				delete ccCampsNvosCB

				SELECT cams.cam_id, cams.cam_descripcion, 
				isNull(wt.New,0) as new, isNull(wt.Cb,0) as cb, 
				isNull(cs.Pend,0) as pend,
				isNull(wt.Pro,0) as pro,
				isNull(cams.cam_procesando,0) cam_procesando, 
				isNull(cams.cam_tipojobs,0) cam_tipojobs,
				isNull(wt.Fin,0) Fin,
				isNull(tc.cantidad,0) cantidad
				FROM ccCamps cams with(nolock)
				LEFT JOIN
				(
					SELECT cam_id,
					count(case cal_status when 0 then 1 else null end) as New,
					count(case cal_status when 1 then 1 else null end) as Cb,
					count(case cal_status when 2 then 1 else null end) as Pro,
					count(case cal_status when 3 then 1 else null end) as Fin
					FROM ccoworkingtable with(index(IX_ccoWorkingTable),nolock)
					GROUP BY cam_id
				) wt on cams.cam_id = wt.cam_id
				LEFT JOIN
				(
					SELECT cam_id, count(cam_id) as Pend
					FROM ccocallsoutsource with(nolock index(IX_ccoCallsOutSource))
					WHERE cal_status in(0, 7)
					GROUP BY cam_id
				) cs on cams.cam_id = cs.cam_id
				left join #Tcamps tc on (tc.cam_id = cams.cam_id)

				drop table #Tcamps
			end

		-- devuelve resultado de la taba, solo las camps del usuario
		SELECT res.id, res.campaña, res.new, res.cb, res.pro, res.pen, res.st, res.job, res.Fin, isnull(prio.prioridad,''12345NNN'') as Prioridad, NextDial
		FROM ccCampsNvosCB res
		LEFT JOIN ccCampsPrioridadTel prio on res.id = prio.cam_id
		WHERE res.id in(select cam_id from ccSupervisorCam where tipo = 1 and user_id = @user_id)

		return(0)
	end

-- Actualiza una camp
if @Tipo=1
	begin
		exec @regval = ccsp_OUTGetNewJobs @cam_id,2,0

		delete ccCampsNvosCB with(rowlock) where id = @cam_id

		SELECT cams.cam_id, cams.cam_descripcion, 
		isNull(wt.New,0) as new, isNull(wt.Cb,0) as cb, 
		isNull(cs.Pend,0) as pend,
		isNull(wt.Pro,0) as pro,
		isNull(cams.cam_procesando,0) cam_procesando, 
		isNull(cams.cam_tipojobs,0) cam_tipojobs,
		isNull(wt.Fin,0) Fin,
		isnull(@regval,0) NextDial
		FROM ccCamps cams with(nolock)
		LEFT JOIN
		(
			SELECT @cam_id as cam_id,
			count(case cal_status when 0 then 1 else null end) as New,
			count(case cal_status when 1 then 1 else null end) as Cb,
			count(case cal_status when 2 then 1 else null end) as Pro,
			count(case cal_status when 3 then 1 else null end) as Fin
			FROM ccoworkingtable with(nolock index(IX_ccoWorkingTable))
			WHERE cam_id = @cam_id

		) wt on cams.cam_id = wt.cam_id
		LEFT JOIN
		(
			SELECT @cam_id as cam_id, count(cam_id) as Pend
			FROM ccocallsoutsource with(nolock index(IX_ccoCallsOutSource_11))
			WHERE cal_status in (0,7) 

			AND cam_id = @cam_id
		) cs on cams.cam_id = cs.cam_id
		WHERE cams.cam_id = @cam_id

		-- devuelve resultado de la taba
		SELECT id, campaña, new, cb, pro, pen,st, job, Fin, isnull(prioridad,''12345NNN'')  as Prioridad, NextDial
		FROM ccCampsNvosCB res

		LEFT JOIN ccCampsPrioridadTel prio on res.id = prio.cam_id
		WHERE res.id = @cam_id

		return(0)
	end

set nocount off'
		EXEC(@sql)


		set @process = 'ALTER PROCEDURE [dbo].[ccsp_CheckDATA] --------------'
		set @sql='ALTER PROCEDURE [dbo].[ccsp_CheckDATA]
AS
set nocount on
 
delete ccInboundAgentes with(rowlock) where user_id not in (select user_id from ccusers where  TipoUser_id=1 and Status=1)
delete ccCampsAgente with(rowlock) where user_id not in (select user_id from ccusers where TipoUser_id=1 and Status=1)
update ccPosicion with(rowlock) set user_id = 0

set nocount off'
		EXEC(@sql)


		set @process = 'ALTER Procedure [dbo].[ccsp_RIAADMGetCalifDayForced] --------------'
		set @sql='ALTER Procedure [dbo].[ccsp_RIAADMGetCalifDayForced]
@type smallint,
@cam_id smallint,
@calif_id smallint = null
AS 
set nocount on
create table #CalifTemp (id int identity,
tipo integer, 
Cam_id varchar(50), 
Calificacion varchar(50), 
subCalificacion varchar(50) null,
calif_id smallint null,
Total int ) 

declare @today datetime
set @today = convert(datetime, convert (varchar(11), getdate(), 101))
--set @today =convert(datetime, convert (varchar(11), ''2015-10-01 17:50:20.470'', 101))

-- Seleccion de idioma -- 
declare @nIdioma varchar(22),@nIdiomaSub varchar(22)
select @nIdioma = case valor when 0 then ''Sin calificación Otros'' else ''No disposition Others'' end
from ccsettings where setting_id = 27 -- 0esp

select @nIdiomaSub = case valor when 0 then ''Sin Subcalificación'' else ''No Subdisposition'' end
from ccsettings where setting_id = 27 -- 0 esp

if @type=0 
select 0 as tipo,co.cam_id as cam_id, case when co.statuscall_id = 13
		then case when description is not null 
					then description 
					else @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
					end
else case when sll.descripcion is not null then ''cw:'' + sll.descripcion else ''cw:'' + @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
end end as Calificacion,
case when count(co.califSub_id) > 0 then 1 else 0 end as Subcalificacion,co.calif_id as calif_id,count(*) cantidad
from ccoCallsOut co with(nolock, index(IX_ccoCallsOut_2))
left join ccTipoCalifOut ca on co.calif_id = ca.calif_id 
left join ccTipoCalifSubOUT tcsout on co.califSub_id = tcsout.califSub_id
left join ccstatusllamada sll on sll.statuscall_id = co.statuscall_id
left join ccCamps ci on ci.cam_id = co.cam_id 
where co.cal_inicio > @today
and co.cam_id = @cam_id
group by  co.cam_id, co.statuscall_id,description,descripcion,co.calif_id



if @type=1 
select 1 as tipo,cci.inbound_id as cam_id, case when description is not null then description 
else @nIdioma-- substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
end as Calificacion,count(ci.califSub_id) as subCalificacion,ci.calif_id,count(*)  as total
from ccCallsIn ci with(nolock, index(IX_ccCallsIn)) 
left join ccTipoCalif ca on ci.calif_id = ca.calif_id 
left join ccInbound cci on cci.inbound_id = ci.inbound_id 
where ci.cal_inicio > @today
and ci.inbound_id = @cam_id
and statuscall_id = 13 
group by description, cci.inbound_id,ci.califSub_id,ci.calif_id



-- Se corrigio suma de totales -- 
Alter table #CalifTemp add iTotal4Campaign int null

if (select valor from ccSettings where setting_id = 78) = 0
update #CalifTemp set iTotal4Campaign = 0

else	
update #CalifTemp set iTotal4Campaign = t.iTotal4Campaign 
from (select cam_id, sum(A.Total) iTotal4Campaign 
from #CalifTemp A group by cam_id) t join #CalifTemp c
on t.cam_id = c.cam_id

if @type=1 
select tipo, cam_id, calificacion,subCalificacion,calif_id ,sum( total ) as totales from (
	select 1 as tipo, inboundId as Cam_id, case when description is not null then description 
	 else @nIdioma --substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	 end as Calificacion,0 as subCalificacion ,0 as calif_id,count(disposition) as Total--,0 as iTotal4Campaign
	from ccriachats a left join ccTipoCalif b 
	on a.disposition=b.calif_id 
	where a.chatDate > @today
	and a.inboundId = @cam_id
	group by inboundId, Description
	
	union all
	
	
	select tipo,Cam_id,case when total > iTotal4Campaign / 100 or calificacion = @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	then calificacion 
	else @nIdioma --substring(@nIdioma, charindex(''@'', @nIdioma)+1, len(@nIdioma)) 
	end as Calificacion,
	case when count(subCalificacion) > 0 then 1 else 0 end subCalificacion,calif_id,sum(Total) as Total  --iTotal4Campaign -- para ver total por campaña
	from #CalifTemp 
	group by tipo, case when total > iTotal4Campaign / 100 or calificacion = @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	then calificacion 
	else @nIdioma--substring(@nIdioma, charindex(''@'', @nIdioma)+1, len(@nIdioma)) 
	end, Cam_id,calif_id, iTotal4Campaign
)  as a group by tipo, cam_id, calificacion,subCalificacion,calif_id order by tipo,cam_id 
if @type=0 

select tipo,Cam_id,case when total > iTotal4Campaign / 100 or calificacion = @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
then calificacion 
else @nIdioma--substring(@nIdioma, charindex(''@'', @nIdioma)+1, len(@nIdioma)) 
end as Calificacion,subCalificacion, calif_id ,sum(Total) as Total -- , iTotal4Campaign -- para ver total por campaña
from #CalifTemp 
group by tipo, case when total > iTotal4Campaign / 100 or calificacion = @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
then calificacion 
else @nIdioma--substring(@nIdioma, charindex(''@'', @nIdioma)+1, len(@nIdioma)) 
end, Cam_id,subCalificacion, calif_id, iTotal4Campaign



if @type = 3 begin -----entrada acd''s
	select 1 as tipo,cci.inbound_id as cam_id, case when description is not null then description 
	else @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	end as Calificacion,isnull(ctcs.califSubDesc,@nIdiomaSub) as subCalificacion, count(*) as totales 
	from ccCallsIn ci with(nolock, index(IX_ccCallsIn)) left join ccTipoCalif ca on ci.calif_id = ca.calif_id 
	left join ccInbound cci on cci.inbound_id = ci.inbound_id 
	left join ccTipoCalifSub ctcs on ci.califSub_id = ctcs.califSub_id
	where ci.cal_inicio > @today
	and ci.inbound_id = @cam_id
	and statuscall_id = 13 
	and ci.calif_id = @calif_id
	group by description, cci.inbound_id,ctcs.califSubDesc,ci.calif_id 
end

if @type = 4 begin --salida campañas
		select 0 as tipo,co.cam_id as cam_id, case when co.statuscall_id = 13 
			then case when description is not null 
						then description 
						else @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
						end
	else case when sll.descripcion is not null 
	then ''cw:'' + sll.descripcion else ''cw:'' + @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	end end as Calificacion,isnull(cso.califSubDesc,@nIdiomaSub) ,count(*) cantidad 
	from ccoCallsOut co with(nolock, index(IX_ccoCallsOut_2))
	left join ccTipoCalifOut ca on co.calif_id = ca.calif_id 
	left join ccTipoCalifSubOUT cso on co.califSub_id = cso.califSub_id
	left join ccstatusllamada sll on sll.statuscall_id = co.statuscall_id
	left join ccCamps ci on ci.cam_id = co.cam_id 
	where co.cal_inicio > @today
	and co.cam_id = @cam_id
	group by  co.cam_id, co.statuscall_id,description,descripcion,cso.califSubDesc
end 
 

drop table #CalifTemp 
set nocount off'
		EXEC(@sql)




		set @process = 'ALTER Procedure [dbo].[ccsp_RIAADMGetCalifDay] --------------'
		set @sql='ALTER Procedure [dbo].[ccsp_RIAADMGetCalifDay]
@type smallint,
@inbound_id smallint = null,
@calif_id smallint = null
AS 
set nocount on
create table #CalifTemp (id int identity,
tipo integer, 
Cam_id varchar(50), 
Calificacion varchar(50), 
subCalificacion varchar(50) null,
calif_id smallint null,
Total int ) 

declare @today datetime
set @today =convert(datetime, convert (varchar(11), getdate(), 101))
--set @today =convert(datetime, convert (varchar(11), ''2015-10-01 17:50:20.470'', 101))

-- Seleccion de idioma -- 
declare @nIdioma varchar(22),@nIdiomaSub varchar(22)
select @nIdioma = case valor when 0 then ''Sin calificación Otros'' else ''No disposition Others'' end
from ccsettings where setting_id = 27 -- 0 esp

select @nIdiomaSub = case valor when 0 then ''Sin Subcalificación'' else ''No Subdisposition'' end
from ccsettings where setting_id = 27 -- 0 esp

if @type=0 
select 0 as tipo,co.cam_id as cam_id, case when co.statuscall_id = 13 
		then case when description is not null 
					then description
					else @nIdioma-- substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
					end
else case when sll.descripcion is not null then ''cw:'' + sll.descripcion 
	else ''cw:'' + @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	end end as Calificacion
,0 as subCalificaion,
co.calif_id,count(*) cantidad 
from ccoCallsOut co with(nolock, index(IX_ccoCallsOut_2))
left join ccTipoCalifOut ca on co.calif_id = ca.calif_id 
left join ccstatusllamada sll on sll.statuscall_id = co.statuscall_id
left join ccCamps ci on ci.cam_id = co.cam_id 
where co.cal_inicio > @today
group by  co.cam_id, co.statuscall_id,description,descripcion,co.calif_id


if @type=1 

select 1 as tipo,cci.inbound_id as cam_id, case when description is not null then description 
else @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
end as Calificacion
,count(isnull(ctcs.califSubDesc,'''')) as subCalificacion,ci.calif_id
,count(*) as total
 
from ccCallsIn ci with(nolock, index(IX_ccCallsIn)) left join ccTipoCalif ca on ci.calif_id = ca.calif_id
left join ccInbound cci on cci.inbound_id = ci.inbound_id 
left join ccTipoCalifSub ctcs on ci.califSub_id = ctcs.califSub_id
where ci.cal_inicio > @today
and statuscall_id = 13 
group by description, cci.inbound_id,ci.calif_id

-- Se corrigio suma de totales -- 
Alter table #CalifTemp add iTotal4Campaign int null

if (select valor from ccSettings where setting_id = 78) = 0
update #CalifTemp set iTotal4Campaign = 0

else	
update #CalifTemp set iTotal4Campaign = t.iTotal4Campaign 
from (select cam_id, sum(A.Total) iTotal4Campaign 
from #CalifTemp A group by cam_id) t join #CalifTemp c
on t.cam_id = c.cam_id

if @type=1 
select tipo, cam_id, calificacion,subCalificacion,calif_id ,sum( total ) as totales from (
	select 1 as tipo, inboundId as Cam_id, case when description is not null then description 
	 else @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	 end as Calificacion
	 , 0 as subCalificacion,0 as calif_id, 	 
	 count(disposition) as Total,0 count,0 iTotal4Campaign
	from ccriachats a left join ccTipoCalif b
	on a.disposition=b.calif_id 
	where a.chatDate > @today
	group by inboundId, Description
	
	union all

	select tipo,Cam_id,case when total > iTotal4Campaign / 100 or calificacion = @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	then calificacion 
	else @nIdioma--substring(@nIdioma, charindex(''@'', @nIdioma)+1, len(@nIdioma)) 
	end as Calificacion
	,case when count(subCalificacion)>0 then 1 else 0 end subCalificacion,
	isnull(calif_id,'''') as calif_id
	 ,sum(Total) as Total, count(*) count , iTotal4Campaign -- para ver total por campaña
	from #CalifTemp 
	group by tipo, case when total > iTotal4Campaign / 100 or calificacion = @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	then calificacion 
	else @nIdioma--substring(@nIdioma, charindex(''@'', @nIdioma)+1, len(@nIdioma)) 
	end,calif_id,Cam_id, iTotal4Campaign
)  as a group by tipo, cam_id, calificacion,subCalificacion,calif_id order by tipo,cam_id,calif_id 

if @type=0 
select tipo,Cam_id,case when total > iTotal4Campaign / 100 or calificacion = @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
then calificacion 
else @nIdioma--substring(@nIdioma, charindex(''@'', @nIdioma)+1, len(@nIdioma)) 
end as Calificacion,case when count(subCalificacion)>0 then 1 else 0 end subCalificacion, calif_id,sum(Total) as Total-- , iTotal4Campaign -- para ver total por campaña
from #CalifTemp 
group by tipo, case when total > iTotal4Campaign / 100 or calificacion = @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
then calificacion 
else @nIdioma--substring(@nIdioma, charindex(''@'', @nIdioma)+1, len(@nIdioma)) 
end, Cam_id, iTotal4Campaign,calif_id


if @type = 3 begin -----entrada acd''s
	select 1 as tipo,cci.inbound_id as cam_id, case when description is not null then description 
	else @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	end as Calificacion,
	isnull(ctcs.califSubDesc,@nIdiomaSub) as subCalificacion
	, count(*) as totales 
	from ccCallsIn ci with(nolock, index(IX_ccCallsIn)) left join ccTipoCalif ca on ci.calif_id = ca.calif_id 
	left join ccInbound cci on cci.inbound_id = ci.inbound_id 
	left join ccTipoCalifSub ctcs on ci.califSub_id = ctcs.califSub_id
	where ci.cal_inicio > @today
	and ci.inbound_id = @inbound_id
	and statuscall_id = 13 
	and ci.calif_id = @calif_id
	group by description, cci.inbound_id,ctcs.califSubDesc,ci.calif_id 
end

if @type = 4 begin --salida campañas
		select 0 as tipo,co.cam_id as cam_id, case when co.statuscall_id = 13 
			then case when description is not null 
						then description 
						else @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
						end
	else case when sll.descripcion is not null 
	then ''cw:'' + sll.descripcion else ''cw:'' + @nIdioma--substring(@nIdioma, 1, charindex(''@'', @nIdioma)-1) 
	end end as Calificacion,isnull(cso.califSubDesc,@nIdiomaSub) ,count(*) cantidad 
	from ccoCallsOut co with(nolock, index(IX_ccoCallsOut_2))
	left join ccTipoCalifOut ca on co.calif_id = ca.calif_id 
	left join ccTipoCalifSubOUT cso on co.califSub_id = cso.califSub_id
	left join ccstatusllamada sll on sll.statuscall_id = co.statuscall_id
	left join ccCamps ci on ci.cam_id = co.cam_id 
	where co.cal_inicio > @today
	and co.cam_id = @inbound_id
	and co.calif_id = @calif_id
	group by  co.cam_id, co.statuscall_id,description,descripcion,cso.califSubDesc
end 


